function storyGraphModel(){const content=activeContent();if(!content)return null;const scenes=content.scenes||[],ids=new Set(scenes.map(s=>s.id)),nodes=[],edges=[],nodeById=new Map(),sceneIndex=new Map(scenes.map((s,i)=>[s.id,i]));const addNode=n=>{nodes.push(n);nodeById.set(n.id,n);return n};const addEdge=e=>{if(e.from&&e.to&&nodeById.has(e.from)&&nodeById.has(e.to))edges.push({...e,id:`edge:${edges.length}:${e.from}:${e.to}`})};
  for(const scene of scenes)addNode({id:`scene:${scene.id}`,kind:'scene',sceneId:scene.id,title:scene.title,chapterTitle:scene.chapterTitle||'Без главы',order:scene.order??sceneIndex.get(scene.id),route:sceneRouteTag(scene.id),start:scene.id===content.startScene,end:sceneHasEnd(scene)});
  const choiceRefs=[];for(const scene of scenes){for(const st of scene.steps||[])if(st.type==='choice'){const id=`choice:${scene.id}:${st.id}`;addNode({id,kind:'choice',sceneId:scene.id,choiceId:st.id,title:st.prompt||st.id,chapterTitle:scene.chapterTitle||'Без главы',order:(scene.order??0)+.25,choice:st});choiceRefs.push({scene,choice:st,id})}}
  for(const {scene,choice,id} of choiceRefs){addEdge({from:`scene:${scene.id}`,to:id,kind:'choice-enter',sceneId:scene.id,choiceId:choice.id});for(const o of choice.options||[]){let raws=[];if(o.goto)raws.push(o.goto);else if(o.fallbackGoto)raws.push(o.fallbackGoto);else raws=collectGraphGotos(o.steps||[]);let ts=[...new Set(raws.flatMap(r=>graphTargetsForRaw(r,ids)))];if(!ts.length){const ni=sceneIndex.get(scene.id)+1;if(scenes[ni])ts=[scenes[ni].id]}for(const t of ts)addEdge({from:id,to:`scene:${t}`,kind:'option',choiceId:choice.id,optionId:o.id,label:o.label||o.id,sceneId:scene.id,targetSceneId:t})}}
  for(const scene of scenes){const hasChoice=(scene.steps||[]).some(st=>st.type==='choice');if(hasChoice)continue;const raws=collectGraphGotos(scene.steps||[],{skipChoices:true}),targets=[...new Set(raws.flatMap(r=>graphTargetsForRaw(r,ids)))];if(targets.length){for(const t of targets)addEdge({from:`scene:${scene.id}`,to:`scene:${t}`,kind:'goto',sceneId:scene.id,targetSceneId:t})}else if(!sceneHasEnd(scene)){const ni=sceneIndex.get(scene.id)+1;if(scenes[ni])addEdge({from:`scene:${scene.id}`,to:`scene:${scenes[ni].id}`,kind:'sequence',sceneId:scene.id,targetSceneId:scenes[ni].id})}}
  const outgoing=new Map(nodes.map(n=>[n.id,0]));for(const e of edges)outgoing.set(e.from,(outgoing.get(e.from)||0)+1);for(const n of nodes)if(n.kind==='scene'&&!outgoing.get(n.id))n.end=true;
  // Compact chapter-based layout: beginning on the left, endings on the right.
  const chapterOrder=[];for(const scene of scenes){const k=scene.chapterTitle||'Без главы';if(!chapterOrder.includes(k))chapterOrder.push(k)}
  const chapterIndex=new Map(chapterOrder.map((c,i)=>[c,i])),groups=new Map(chapterOrder.map(c=>[c,[]]));for(const n of nodes)groups.get(n.chapterTitle||'Без главы')?.push(n);
  const bandW=252,xGap=34,nodeW=216,nodeH=66,choiceH=78,top=82,left=34,rowGap=18,pos=new Map(),bands=[];let maxBottom=720;
  for(const chapter of chapterOrder){const ci=chapterIndex.get(chapter),x=left+ci*(bandW+xGap),arr=groups.get(chapter)||[];arr.sort((a,b)=>(a.order??0)-(b.order??0)||((a.kind==='scene'?0:1)-(b.kind==='scene'?0:1))||a.id.localeCompare(b.id));let y=top+38;for(const n of arr){const h=n.kind==='choice'?choiceH:nodeH;pos.set(n.id,{x:x+18,y,w:nodeW,h,chapterIndex:ci});y+=h+rowGap}const bh=Math.max(610,y-top+22);bands.push({chapter,index:ci,x,y:top-16,w:bandW,h:bh});maxBottom=Math.max(maxBottom,top-16+bh)}
  const width=left*2+chapterOrder.length*(bandW+xGap)-xGap,height=maxBottom+44;
  const incoming=new Map(nodes.map(n=>[n.id,[]])),outMap=new Map(nodes.map(n=>[n.id,[]]));for(const e of edges){incoming.get(e.to)?.push(e);outMap.get(e.from)?.push(e)}
  return{nodes,edges,nodeById,pos,width,height,bands,chapterOrder,incoming,outgoing:outMap};}
function graphReviewCounts(){const m=new Map();for(const r of app.activeVersion?.reviews||[]){if(CLOSED_REVIEW_STATUSES.has(r.status))continue;const ref=P.getFragmentRef(activeContent(),r.fragmentId);if(ref)m.set(ref.scene.id,(m.get(ref.scene.id)||0)+1)}return m}
function graphVisitedScenes(){return new Set((app.session?.timeline||[]).map(e=>e.sceneId).filter(Boolean))}
function graphSelectedChoices(){const m=new Map();for(const c of app.session?.choices||[])m.set(`${c.sceneId}|${c.choiceId}`,c.optionId);return m}
function graphWalk(g,startId,direction='out'){const seen=new Set(),stack=[startId];while(stack.length){const id=stack.pop();if(seen.has(id))continue;seen.add(id);const es=direction==='in'?(g.incoming.get(id)||[]):(g.outgoing.get(id)||[]);for(const e of es)stack.push(direction==='in'?e.from:e.to)}return seen}
function graphFocusSets(g){if(!g)return{nodes:null,edges:null};const mode=app.graphFocusMode||'none',id=app.graphFocusNode||app.graphSelectedNode;if(mode==='none'||!id)return{nodes:null,edges:null};let ns;if(mode==='ancestors')ns=graphWalk(g,id,'in');else if(mode==='descendants')ns=graphWalk(g,id,'out');else if(mode==='active'){ns=new Set();const visited=graphVisitedScenes();for(const sid of visited)ns.add(`scene:${sid}`);for(const e of g.edges)if(e.kind==='choice-enter'&&visited.has(e.sceneId))ns.add(e.to);const sel=graphSelectedChoices();for(const e of g.edges)if(e.kind==='option'&&sel.get(`${e.sceneId}|${e.choiceId}`)===e.optionId){ns.add(e.from);ns.add(e.to)}}else ns=null;if(!ns)return{nodes:null,edges:null};const es=new Set(g.edges.filter(e=>ns.has(e.from)&&ns.has(e.to)).map(e=>e.id));return{nodes:ns,edges:es}}
function graphSimplePathCount(g,startId,endId,cap=9999){const memo=new Map(),visiting=new Set();function dfs(id){if(id===endId)return 1;if(memo.has(id))return memo.get(id);if(visiting.has(id))return 0;visiting.add(id);let total=0;for(const e of g.outgoing.get(id)||[]){total+=dfs(e.to);if(total>=cap){total=cap;break}}visiting.delete(id);memo.set(id,total);return total}return dfs(startId)}
function graphPathLabel(){if(app.graphFocusMode==='ancestors')return'Пути к выбранному узлу';if(app.graphFocusMode==='descendants')return'Ветки от выбранного узла';if(app.graphFocusMode==='active')return'Текущее прохождение';return''}
