function graphEdgePath(a,b){const same=(a.chapterIndex===b.chapterIndex),x1=same?a.x+a.w/2:a.x+a.w,y1=same?a.y+a.h:a.y+a.h/2,x2=same?b.x+b.w/2:b.x,y2=same?b.y:b.y+b.h/2;if(same){const my=(y1+y2)/2;return`M ${x1} ${y1} C ${x1} ${my}, ${x2} ${my}, ${x2} ${y2}`}const mx=(x1+x2)/2;return`M ${x1} ${y1} C ${mx} ${y1}, ${mx} ${y2}, ${x2} ${y2}`}
function graphCoverage(){const g=app.storyGraph||storyGraphModel(),visited=graphVisitedScenes(),sceneTotal=g?.nodes.filter(n=>n.kind==='scene').length||0,choiceTotal=g?.nodes.filter(n=>n.kind==='choice').length||0,taken=new Set((app.session?.choices||[]).map(c=>`${c.sceneId}|${c.choiceId}`));return{visited:visited.size,sceneTotal,taken:taken.size,choiceTotal}}
function renderGraphEndingJumps(){const host=$('graphEndingJumps');if(!host||!app.storyGraph)return;const ends=app.storyGraph.nodes.filter(n=>n.kind==='scene'&&n.end);host.innerHTML=ends.map(n=>`<button type="button" class="graph-ending-chip ${app.graphSelectedNode===n.id?'active':''}" data-ending-node="${esc(n.id)}"><span>${esc(n.route?.label||'Концовка')}</span><small>${esc(n.sceneId)}</small></button>`).join('');host.querySelectorAll('[data-ending-node]').forEach(b=>b.addEventListener('click',()=>{app.graphSelectedNode=b.dataset.endingNode;app.graphFocusMode='ancestors';app.graphFocusNode=b.dataset.endingNode;renderStoryGraph();setTimeout(()=>document.querySelector(`[data-graph-node="${CSS.escape(b.dataset.endingNode)}"]`)?.scrollIntoView({block:'center',inline:'center'}),20)}))}
function exportStoryGraphSvg(){const svg=$('branchGraphSvg');if(!svg)return;const copy=svg.cloneNode(true);copy.setAttribute('xmlns','http://www.w3.org/2000/svg');copy.setAttribute('width',svg.dataset.baseWidth||svg.getAttribute('viewBox')?.split(' ')[2]||'1600');copy.setAttribute('height',svg.dataset.baseHeight||svg.getAttribute('viewBox')?.split(' ')[3]||'900');const style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent=`.story-edge{fill:none;stroke:#b8b8b8;stroke-width:1.4}.story-edge.selected,.story-edge.focused{stroke:#15936e;stroke-width:2.6}.story-node rect{fill:#fff;stroke:#bbb}.story-node.choice rect{fill:#f8f5ff;stroke:#bfa9e3}.story-node.current rect{fill:#eefaf6;stroke:#15936e;stroke-width:3}.story-node text{font-family:Arial,sans-serif;fill:#111}.graph-chapter-band{fill:#fafafa;stroke:#e5e5e5}.graph-chapter-title{font:700 12px Arial;fill:#555}`;copy.prepend(style);const blob=new Blob([new XMLSerializer().serializeToString(copy)],{type:'image/svg+xml;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${slug(app.activeNovel?.title||'heartline')}-story-graph.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

function graphFilterMatch(n,visited,reviews){const f=app.graphFilter||'all',q=(app.graphSearch||'').trim().toLowerCase();let ok=true;if(f==='current')ok=n.kind==='scene'?visited.has(n.sceneId):visited.has(n.sceneId);else if(f==='unread')ok=n.kind==='scene'?!visited.has(n.sceneId):!visited.has(n.sceneId);else if(f==='reviews')ok=(reviews.get(n.sceneId)||0)>0;else if(f==='endings')ok=n.kind==='scene'&&n.end;if(q)ok=ok&&`${n.sceneId||''} ${n.choiceId||''} ${n.title||''}`.toLowerCase().includes(q);return ok}
