function applyGraphZoom(){const svg=$('branchGraphSvg');if(!svg)return;const bw=Number(svg.dataset.baseWidth||1200),bh=Number(svg.dataset.baseHeight||800),z=Math.max(.22,Math.min(1.8,app.graphZoom||1));app.graphZoom=z;svg.style.width=`${Math.round(bw*z)}px`;svg.style.height=`${Math.round(bh*z)}px`;$('graphZoomLabel').textContent=`${Math.round(z*100)}%`}
