function graphZoomAtPoint(vp,clientX,clientY,factor){const oldZ=app.graphZoom||1,newZ=Math.max(.22,Math.min(1.8,oldZ*factor));if(Math.abs(newZ-oldZ)<.0001)return;const rect=vp.getBoundingClientRect(),cx=clientX-rect.left,cy=clientY-rect.top,contentX=(vp.scrollLeft+cx)/oldZ,contentY=(vp.scrollTop+cy)/oldZ;app.graphZoom=newZ;applyGraphZoom();vp.scrollLeft=contentX*newZ-cx;vp.scrollTop=contentY*newZ-cy}
