function clearActive(){app.activeNovelId=null;app.activeVersionId=null;app.activeNovel=null;app.activeVersion=null;app.session=null;app.editorCursorFragmentId=null;app.previewCandidateId=null;app.editorReturnSession=null;app.editorPreviewSourceFragmentId=null}
async function saveVersion(){if(app.activeVersion){app.activeVersion.updatedAt=now();await DB.put('versions',app.activeVersion);const i=app.versions.findIndex(v=>v.versionId===app.activeVersion.versionId);if(i>=0)app.versions[i]=app.activeVersion;}}
