function openCandidate(id){const c=app.candidates.find(x=>x.candidateId===id);if(!c)return;app.candidateOpenId=id;app.previewCandidateId=id;renderCandidateDialog(c);$('candidateDialog').showModal()}
function renderCandidateDialog(c){const base=getVersion(c.baseVersionId),accepted=c.changes.filter(x=>x.decision==='accepted'&&!x.conflict).length;$('candidateDialogBody').innerHTML=`<div class="validation-summary"><span class="pill">${c.changes.length} изменений</span><span class="pill good">${accepted} принято</span><span class="pill warn">${c.changes.filter(x=>x.decision==='pending').length} ожидают решения</span><span class="pill bad">${c.changes.filter(x=>x.conflict).length} конфликтов</span></div>${accepted?`<div class="validation-item" style="margin:10px 0 14px;background:#f2fbf7;border-color:#b7e4d5"><strong>Предпросмотр включён.</strong><br>Принятые правки уже можно открыть в тексте. Чтобы зафиксировать их как новую редакцию сценария, нажмите «Создать новую версию».</div>`:''}<div class="diff-list">${c.changes.map((ch,i)=>`<article class="diff-card" data-candidate-change="${i}"><div class="diff-head"><span>${esc(P.getFragmentRef(base.content,ch.fragmentId)?.scene?.id||'Фрагмент не найден')} · ${esc(ch.reason||'Без пояснения')}</span><span class="mono">${esc(ch.fragmentId)}</span></div><div class="diff-grid"><div class="diff-pane">${esc(ch.currentText??ch.originalText??'—')}</div><div class="diff-pane">${esc(ch.revisedText??'—')}</div></div>${ch.conflict?'<div class="diff-reason" style="color:#a02b2b">Конфликт: originalText из ответа GPT не совпадает с текущим текстом базовой версии.</div>':''}<div class="diff-actions"><button type="button" class="btn ${ch.decision==='accepted'?'accent':'secondary'} small" data-cand-accept="${i}" ${ch.conflict?'disabled':''}>${ch.decision==='accepted'?'Принято ✓':'Принять'}</button><button type="button" class="btn ${ch.decision==='rejected'?'danger':'secondary'} small" data-cand-reject="${i}">Отклонить</button>${ch.decision==='accepted'?`<button type="button" class="btn secondary small" data-cand-preview="${i}">Показать в тексте</button>`:''}<span class="pill">${esc(ch.decision)}</span></div></article>`).join('')}</div>`;$('candidateDialogFooter').innerHTML=`<button type="button" id="acceptAllCandidate" class="btn secondary">Принять все без конфликтов</button><button type="button" id="finalizeCandidateBtn" class="btn primary" ${accepted?'':'disabled'}>${accepted?`Создать новую версию · ${accepted}`:'Сначала примите правки'}</button>`;document.querySelectorAll('[data-cand-accept]').forEach(b=>b.addEventListener('click',()=>setCandidateDecision(c,Number(b.dataset.candAccept),'accepted')));document.querySelectorAll('[data-cand-reject]').forEach(b=>b.addEventListener('click',()=>setCandidateDecision(c,Number(b.dataset.candReject),'rejected')));document.querySelectorAll('[data-cand-preview]').forEach(b=>b.addEventListener('click',()=>previewCandidateChange(c,Number(b.dataset.candPreview))));$('acceptAllCandidate').addEventListener('click',async()=>{for(const ch of c.changes)if(!ch.conflict&&ch.decision==='pending')ch.decision='accepted';app.previewCandidateId=c.candidateId;await DB.put('candidates',c);renderCandidateDialog(c)});$('finalizeCandidateBtn').addEventListener('click',()=>finalizeCandidate(c))}
async function setCandidateDecision(c,i,d){c.changes[i].decision=d;if(c.changes.some(x=>x.decision==='accepted'&&!x.conflict))app.previewCandidateId=c.candidateId;else if(app.previewCandidateId===c.candidateId)app.previewCandidateId=null;await DB.put('candidates',c);renderCandidateDialog(c)}
